using System;

public class WaterTank
{
    public double Capacity { get; }              // set once, in the constructor
    public double Level { get; private set; }    // read anywhere, changed only in here

    public WaterTank(double capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        Capacity = capacity;
    }

    public double PercentFull => Math.Round(Level / Capacity * 100, 1);

    public double Fill(double litres)
    {
        double added = Math.Min(Capacity - Level, litres);
        Level += added;
        return litres - added;                   // what spilled over
    }
}

