using System;
using System.Collections.Generic;
using System.Linq;

public class WaterTank
{
    public double Capacity { get; }
    public double Level { get; private set; }

    public WaterTank(double capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity), "A tank needs room for some water.");
        Capacity = capacity;
    }

    public double PercentFull => Math.Round(Level / Capacity * 100, 1);

    // Adds what fits and returns what spilled over the top.
    public double Fill(double litres)
    {
        if (litres < 0) throw new ArgumentOutOfRangeException(nameof(litres));
        double added = Math.Min(Capacity - Level, litres);
        Level += added;
        return litres - added;
    }

    // Takes out up to `litres` and returns what was really drawn.
    public double Draw(double litres)
    {
        if (litres < 0) throw new ArgumentOutOfRangeException(nameof(litres));
        double taken = Math.Min(Level, litres);
        Level -= taken;
        return taken;
    }
}

