using System;
using System.Collections.Generic;
using System.Linq;

public class PlayerProfile
{
    private readonly string name = "Player";
    private int volume = 80;

    // init: can be set once while the object is being made, then never again.
    public string Name
    {
        get => name;
        init
        {
            if (string.IsNullOrWhiteSpace(value)) throw new ArgumentException("A name can't be blank.");
            name = value.Trim();
        }
    }

    // Whatever comes in, the stored value stays between 0 and 100.
    public int Volume
    {
        get => volume;
        set => volume = Math.Clamp(value, 0, 100);
    }

    public int Xp { get; private set; }

    public int Level => Xp / 100 + 1;

    public void AddXp(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        Xp += amount;
    }
}

