using System;
using System.Collections.Generic;
using System.Linq;

public class Ticket
{
    // static: one counter for the whole class, not one per ticket
    public static int Issued { get; private set; }

    public int Number { get; }
    public string Patient { get; }

    public Ticket(string patient)
    {
        if (string.IsNullOrWhiteSpace(patient)) throw new ArgumentException("Who is the ticket for?");
        Patient = patient.Trim();
        Issued++;
        Number = Issued;
    }

    public static void ResetDay() => Issued = 0;

    public static string NextUp(int served) => served >= Issued ? "Queue empty" : $"Now serving #{served + 1}";

    public override string ToString() => $"#{Number} {Patient}";
}
